function(params){
  if (game.state !== 'play') return { message: '⚠️ 请先按 Enter 开始游戏再使用道具', error: true };
  var sec = (params && params.seconds) ? params.seconds : 10;
  var w = (params && params.weapon) ? params.weapon : 'ice';
  var r = api.startWeapon(w, sec * 60);
  if (r && r.applied === false) return { message: '⚠️ ' + (r.reason || '使用失败'), error: true };
  return { message: '❄️ 冰冻术已装备！按住 X/Z 发射冰锥，剩余 ' + sec + ' 秒' };
}
